scwin.onpageload = async function() {
    try {
        scwin.resoroomId;
        scwin.fileRowcount;
        scwin.mvFileExist = 'N';

        // 회사코드 취득
        let isurInfo = [];
        const _Option = {
            id : "sbm_isurCode",
            action : "/ui/dis/sample/JsonData/isuInfo.data",
            method: "get",
            isProcessMsg : false
        };
        isurInfo =  await $c.sbm.executeDynamic(_Option, {});	
        let isurInfoArr = JSON.parse(isurInfo.responseText);
        MxDataSet_com_isur.setData(isurInfoArr);
        //

        scwin.gform_onload ();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30305.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.img_com_srch_onclick" });
    }
};

scwin.moveData_OnClick = function() {
    try {
        const mv_filenm = mv_attach_file_nm.getValue();
        if (scwin.resoroomId === 'input') {
            dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", moveData.Value);
        } else {
            /*	
    		if (mvFileExist  == 'Y') {
    dts_fileDataUpdate.setNameValue(dts_fileDataUpdate.rowposition, "fileInfo",moveData.Value) 
    		} else {
    dts_fileData.setNameValue(dts_fileData.rowposition, "fileInfo",moveData.Value) 
    		}
    		*/
            dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", moveData.Value);
        }
        mv_attach_file_nm.setValue(moveData.value);
        if (moveData.Value === "") {
            mv_attach_file_nm.setValue(mv_filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.moveData_OnClick" });
    }
};

