scwin.save_onclick = function() {
    try {
        if (scwin.resoroomId !== "input") {
            scwin.update();
        } else {
            scwin.save();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.save_onclick" });
    }
};

