scwin.btn_lineadd_onclick = function() {
    try {
        if (scwin.resoroomId !== "input") {
            scwin.fileRowcount = dts_fileList.getRowCount();
        }
        scwin.fileRowcount++;
        if (scwin.fileRowcount >= 3) {
            alert("더이상 추가하실수 없습니다.");
            scwin.fileRowcount = 3;
        } else {
            dts_fileList.insertRow();

            inf_find.open();
            if (inf_find.Value !== "") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
                file_name.setValue(inf_find.Value);
            } else {
                dts_fileList.removeRows(dts_fileList.getRowPosition());
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.btn_lineadd_onclick" });
    }
};

scwin.btn_linedelete_onclick = function() {
    try {
        if (scwin.fileRowcount > 0) scwin.fileRowcount--;
        dts_fileList.removeRows(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.btn_linedelete_onclick" });
    }
};

scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.Value);
        file_name.setValue(inf_find.Value);
        if (inf_find.Value === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.inf_find_OnClick" });
    }
};

scwin.mv_attach_file_nm_onclick = function() {
    try {
        if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) === 0) {
            scwin.filedown(dts_fileData.getCellData(0, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.mv_attach_file_nm_onclick" });
    }
};

scwin.grd_userlist_OnClick = function(row, colid) {
    try {
        // 2009-03-11
        if (row === 0) return;
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            scwin.filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30305.grd_userlist_OnClick" });
    }
};

scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
