scwin.update = function() {
    // IR자료실 수정
    if (txb_isur_cd.getValue() === "" || txb_isur_cd.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (title.getValue() === "" || title.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "제목"));
        title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(title, 200, "제목")) {
        title.setValue("");
        title.focus();
        return false;
    }

    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
    /*
    if( koreng_tp_cd.CodeValue == '1') {
    	txb_irhlddate.Text = "";
    }
    */

    /*
    // 동영상 필수 제거 : 2008.10.22
    if(mv_attach_file_nm.value == "" || mv_attach_file_nm.value.indexOf(" ") == "" ) {
    	alert("[동영상 파일은] 반드시 첨부하셔야합니다.");
    	mv_attach_file_nm.focus();
    	return;
    }
    */

    // 동영상이 없으면 첨부파일은 있어야함.
    if (mv_attach_file_nm.getValue() === "" || mv_attach_file_nm.getValue().indexOf(" ") === "") {
        let fileCnt = dts_fileList.getRowCount();
        if (fileCnt <= 0) {
            alert("[동영상 파일 또는 첨부파일]은 반드시 첨부하셔야합니다.");
            mv_attach_file_nm.focus();
            return;
        }
    }
    if (content.getValue() === "" || content.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "내용"));
        content.Focus();
        return;
    }
    if (!scwin.checkMaxLength2(content, 200, "내용")) {
        content.setValue("");// = "";
        content.focus();
        return false;
    }
    if (cast_yn.getValue() === 'Y' & submit_yn.getValue() === 'N') {
        // 상장법인제출여부가 Y가 아니면 공개여부를 Y로 설정할 수 없음
        alert("[상장법인 제출여부] 가 Y일 경우에만 [공개여부]를 YES로 설정 가능합니다.");
        cast_yn.focus();
        cast_yn.setValue('N');
        return;
    }
    let rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

/* 업데이트 서비스 개발 필요
        trs_Update.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/IRMgt.do",
            ref : "dts_irDataRoomSingle,dts_fileData,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    //업데이트 서비스 개발 후 처리 
    //성공시 
    scwin.trs_Update_OnSuccess();
    //실패시
    scwin.trs_Update_OnFail();
*/
    // 업데이트 성공했다 치고
    scwin.trs_Update_OnSuccess();

    }
};

scwin.save = function() {
    // IR자료실 등록
    /* 파일업로드 */
    if (txb_isur_cd.getValue() === "" || txb_isur_cd.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (title.getValue() === "" || title.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "제목"));
        title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(title, 200, "제목")) {
        title.setValue("");
        title.focus();
        return false;
    }

    // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
    /*
