    }
    */

    /*
    // 동영상 필수 제거 : 2008.10.22		
    if(mv_attach_file_nm.value == "" || mv_attach_file_nm.value.indexOf(" ") == "" ) {
    	alert("[동영상 파일은] 반드시 첨부하셔야합니다.");
    	mv_attach_file_nm.focus();
    	return;
    }
    */

    // 동영상이 없으면 첨부파일은 있어야함.
    if (mv_attach_file_nm.getValue() === "" || mv_attach_file_nm.getValue().indexOf(" ") === "") {
        let fileCnt = dts_fileList.getRowCount();
        if (fileCnt <= 0) {
            alert("[동영상 파일 또는 첨부파일]은 반드시 첨부하셔야합니다.");
            mv_attach_file_nm.focus();
            return;
        }
    }
    if (content.getValue() === "" || content.getValue().indexOf(" ") === "") {
        alert($c.stf.getMessageParam("MSG-A005", "내용"));
        content.Focus();
        return;
    }
    if (!scwin.checkMaxLength2(content, 200, "내용")) {
        content.setValue("");
        content.focus();
        return false;
    }
    let rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        usr_id.setValue($c.session.info("js_id"));
/*  업데이트 서비스 개발 필요      

        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/IRMgt.do",
            ref : "dts_irDataSaveInfo,dts_fileData,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    // 저장성공시
    scwin.trs_Save_OnSuccess();
    // 저장 실패시
    scwin.trs_Save_OnFail 
*/

    }
};

