scwin.gform_onload = function() {
// 스타일    $c.libRoundPanel.PanelToGroupBox(panel_Top);

    const reId = $c.win.getParent().scwin.fn_getId;

    scwin.resoroomId = reId();
    // 수정화면 onload
    if (scwin.resoroomId !== "input") {
        scwin.singleRead();
        mv_attach_file_nm.setReadOnly(true);
        if (dts_fileData.getRowCount() === 0 || dts_fileData.getCellData(0, "PIC_YN") === '') {

            // dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
            dts_fileData.insertRow();
        }

        // 2009-03-26
        if ($c.session.info("js_id") !== "999999") {
        // change_movie.style.display = 'none';
            change_movie.hide();
        }

        // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ
        /*
        if(koreng_tp_cd.CodeValue == '1') {
        	txb_irhlddate.ReadOnly = "true";
        } else {
        	txb_irhlddate.ReadOnly = "false";
        }
        */
        cast_yn.setValue('Y');
    } else {
        // 등록화면 onload
        scwin.setIrInfoHeader();
        // dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_fileData.insertRow();
        // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        cast_yn.setValue("Y");
        scwin.fileRowcount = 0;
        edt_Date.setValue($c.ut.cGetToday("yyyymmdd"));
        usr_id.setValue(js_emp_nm);
        // 2009-03-18
        // change_movie.style.display = 'none';
        change_movie.hide();
        // label_14.style.display = 'none';
        label_14.hide();
        koreng_tp_cd.setValue('1'); // 디폴트 국문으로 셋팅.		
        // txb_irhlddate.ReadOnly = "true"; // 기능 변경으로 국문/영문 모두에서 IR개최일 수정할 수 있도록 변경 20130123_by LDJ

    }
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    cast_yn.setValue('Y');
};
